import { Controller } from "@hotwired/stimulus"
import { formatAbsoluteDateTime, formatLocalTime } from "helpers/local_time_helpers"

export default class extends Controller {
  static values = { format: { type: String, default: "smart" } }

  connect() {
    const timestamp = new Date(this.element.dateTime)

    if (!Number.isNaN(timestamp.getTime())) {
      const label = formatAbsoluteDateTime(timestamp)
      this.element.textContent = formatLocalTime(timestamp, this.formatValue)
      this.element.setAttribute("aria-label", label)

      if (!this.element.hasAttribute("title")) this.element.title = label
    }
  }
}
