module CurrentTimezone
  extend ActiveSupport::Concern

  included do
    around_action :set_current_timezone

    helper_method :timezone_from_cookie

    # Authenticated layouts render a timezone-sync form when this cookie changes.
    etag { timezone_from_cookie if Current.user }
  end

  private
    def set_current_timezone(&)
      Time.use_zone(timezone_from_cookie, &)
    end

    def timezone_from_cookie
      @timezone_from_cookie ||= begin
        timezone = cookies[:timezone]
        ActiveSupport::TimeZone[timezone] if timezone.present?
      end
    end
end
require "test_helper"

class CurrentTimezoneTest < ActionDispatch::IntegrationTest
  test "public card timestamps are timezone-neutral in the server response" do
    sign_in_as :kevin
    boards(:writebook).publish
    key = boards(:writebook).publication.key
    card = cards(:logo)
    sign_out

    cookies[:timezone] = "America/New_York"
    get public_board_card_path(key, card)
    assert_response :success
    assert_select "time[datetime]"
    assert_select "meta[name=timezone]", count: 0
    timestamps = timestamp_markup

    cookies[:timezone] = "America/Los_Angeles"
    get public_board_card_path(key, card)
    assert_response :success
    assert_equal timestamps, timestamp_markup
  end

  test "timezone-independent responses keep a shared ETag" do
    cookies[:timezone] = "America/New_York"
    get user_avatar_path(users(:kevin))
    etag = response.headers.fetch("ETag")

    cookies[:timezone] = "America/Los_Angeles"
    get user_avatar_path(users(:kevin)), headers: { "If-None-Match" => etag }
    assert_response :not_modified
    assert_equal etag, response.headers.fetch("ETag")
  end

  test "day timeline ETags still vary when the timezone changes its date window" do
    sign_in_as :kevin
    travel_to Time.utc(2025, 1, 22, 7)

    cookies[:timezone] = "America/New_York"
    get events_path
    etag = response.headers.fetch("ETag")

    cookies[:timezone] = "America/Los_Angeles"
    get events_path, headers: { "If-None-Match" => etag }
    assert_response :success
    assert_not_equal etag, response.headers.fetch("ETag")
  end

  private
    def timestamp_markup
      css_select("time[datetime]").map do |element|
        [ element["datetime"], element["data-local-time-format-value"], element.text ]
      end
    end
